from pathlib import Path
import json,sqlite3,hashlib,shutil,sys,subprocess,tomllib
repo=Path.cwd();sys.path.insert(0,str(repo/'src'))
from rob2_kit.packs import SCIENTIFIC_PACK
sha=subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip();assert sha=='9d286517f2ea9a48c1306579469c4af9924ed5f3';assert not subprocess.check_output(['git','status','--porcelain'])
r=repo.parent/'diagnostics/frozen-bendix-review-9d28651';assert not r.exists();r.mkdir();(r/'workspace').mkdir();(r/'home').mkdir()
audit=repo/'docs/evaluation/2026-10-03-bendix-production-d2';visibility=repo/'docs/evaluation/2026-10-03-bendix-review-visibility'
draft=json.loads((audit/'committed-domain.json').read_text());manifest=json.loads((audit/'manifest.json').read_text());views=json.loads((visibility/'public-selected-review-pages.json').read_text());guidance=[q.model_dump(mode='json') for q in SCIENTIFIC_PACK.questions if q.id.startswith('sq:deviations:')]
source=repo.parent/'diagnostics/frozen-bendix-d2-edf55fa/workspace/.rob2-kit/derivative.sqlite3';pages=[]
with sqlite3.connect(f'file:{source}?mode=ro',uri=True) as c:
 for pg in range(2,7):
  sid,text=c.execute('select source_id,text from pages where page=?',(pg,)).fetchone();pages.append({'source_id':sid,'page':pg,'numbered_text':'\n'.join(f'{i}|{line}' for i,line in enumerate(text.splitlines(),1))})
skill=(repo/'src/rob2_kit/skills/rob2-assess/SKILL.md').read_text();start=skill.index('Inspect the review\'s exact Result');end=skill.index('Close the Trial',start);instruction=skill[start:end]
materials={'approved_target':manifest['approved_target'],'reported_result':manifest['reported_result'],'frozen_domain_draft':draft,'complete_selected_answer_views':views,'primary_source_pages':pages,'source_inventory':manifest['restored_sources'],'current_full_D2_question_guidance':guidance,'generic_review_instruction':instruction}
(r/'frozen-review-materials.json').write_text(json.dumps(materials,ensure_ascii=False,indent=2)+'\n')
prompt='Review the supplied frozen Domain draft and original primary-source evidence using the complete current production D2 question guidance and generic review instruction below. This is one supplied-evidence review response, not a new autonomous assessment or Trial closure. Return proposed answer, warrant and uncertainty revisions with source references, or explain why retaining the draft is justified. Review only the supplied Domain. No tools, outside evidence, code, follow-up or additional response.\n\n'+json.dumps(materials,ensure_ascii=False,indent=2)
(r/'prompt.txt').write_text(prompt);(r/'instructions.md').write_text('Review the supplied scientific assessment and evidence using the supplied current production instructions. Produce exactly one final response. Use no tools, outside evidence or follow-up.\n')
prior=repo.parent/'diagnostics/frozen-bendix-d2-edf55fa'
for name in ['auth.json','models_cache.json']:shutil.copyfile(prior/'home'/name,r/'home'/name)
config=(prior/'home/config.toml').read_text().split('[mcp_servers.rob2]')[0].replace(str(prior/'instructions.md'),str(r/'instructions.md'));config+='code_mode = {enabled=false}\n';(r/'home/config.toml').write_text(config)
conf=tomllib.loads(config);assert conf['model']=='gpt-6-luna' and conf['model_reasoning_effort']=='medium' and 'mcp_servers' not in conf
(r/'observer-criteria.json').write_text(json.dumps({'criteria':['Support an exclusion mechanism over source-supported alternatives; contactability is not observed workability and noncompletion/missingness overlap.','Calibrate definitive versus probable certainty without forcing an answer.','Propagate unresolved mechanism to conditional D2.7 participant population; noncompleters/allnotanalyzed are not automatic D2 numerators.'],'retaining_draft_can_pass':True,'no_label_agreement_scoring':True,'no_retry_or_repair':True,'not_in_model_prompt':True},indent=2)+'\n')
m={'code_sha':sha,'model':'gpt-6-luna','effort':'medium','prompt_sha256':hashlib.sha256(prompt.encode()).hexdigest(),'materials_sha256':hashlib.sha256((r/'frozen-review-materials.json').read_bytes()).hexdigest(),'instruction_sha256':hashlib.sha256((r/'instructions.md').read_bytes()).hexdigest(),'source_page_scope':'Original captured main pages2–6, exact full pages rather than reviewer-selected critical sentences.','guidance_scope':'All seven current D2 questions, complete unchanged fields.','guards':{'wall_seconds':300,'idle_seconds':120,'output_tokens':5000,'input_tokens':None,'tools':0},'classification':'One supplied-evidence review of known frozen draft; not autonomous full workflow, product intervention or independent human adjudication','one_response_only':True,'no_retry':True,'preflight_prompt_bytes':len(prompt.encode())};(r/'manifest.json').write_text(json.dumps(m,indent=2)+'\n');print(r,len(prompt.encode()))
